insert into private.feedback_arabic_translations (kind,he,ar) values
('question','אחרי ההכשרה אני מבין/ה היטב את מטרות התוכנית ואת התוכן שאעביר','بعد التدريب، أفهم جيدًا أهداف البرنامج والمحتوى الذي سأقدّمه'),
('question','אחרי התוכנית אני מרגיש/ה בטוח/ה יותר להתנסות – לבנות, לחקור ולהמציא בעצמי','بعد البرنامج، أشعر بثقة أكبر لتجربة البناء والبحث والابتكار بنفسي'),
('question','איזה הישג משמעותי ראית אצל התלמידים, ומה כדאי לשפר בקורס?','ما الإنجاز المهم الذي لاحظته لدى الطلاب، وما الذي ينبغي تحسينه في الدورة؟'),
('question','איזה הישג משמעותי ראית אצל התלמידים, ומה כדאי לשפר?','ما الإنجاز المهم الذي لاحظته لدى الطلاب، وما الذي ينبغي تحسينه؟'),
('question','איזה חלק בתוכן היית משנה?','أي جزء من المحتوى كنت ستغيّره؟'),
('question','איזה חלק בתוכנית היה הכי מעניין או משמעותי בשבילך?','أي جزء من البرنامج كان الأكثر إثارة للاهتمام أو أهمية بالنسبة إليك؟'),
('question','איזה חלק בתוכנית עבד הכי טוב?','أي جزء من البرنامج نجح أكثر من غيره؟'),
('question','איזה מפגש או פעילות דורשים שינוי? מה לא עבד ומה היית מציע/ה לעשות אחרת?','أي لقاء أو نشاط يحتاج إلى تغيير؟ ما الذي لم ينجح، وماذا تقترح أن نفعل بشكل مختلف؟'),
('question','איזה מפגש או פעילות חשוב לשמר, ומדוע?','أي لقاء أو نشاط من المهم الحفاظ عليه، ولماذا؟'),
('question','איזה מפגש או פעילות כדאי במיוחד לשמר, ומדוע?','أي لقاء أو نشاط يستحق الحفاظ عليه بشكل خاص، ولماذا؟'),
('question','איזה מפגש או פעילות כדאי לשמר במיוחד, ומדוע?','أي لقاء أو نشاط ينبغي الحفاظ عليه بشكل خاص، ولماذا؟'),
('question','איזה מפגש או פעילות כדאי לשמר במיוחד, ומה גרם לה להצליח עם הנערות?','أي لقاء أو نشاط ينبغي الحفاظ عليه بشكل خاص، وما الذي جعله ناجحًا مع الفتيات؟'),
('question','איזה מפגש או פעילות כדאי לשנות? מה לא עבד, ומה היית מציע/ה לעשות אחרת?','أي لقاء أو نشاط ينبغي تغييره؟ ما الذي لم ينجح، وماذا تقترح فعله بشكل مختلف؟'),
('question','איזה מפגש או רכיב בקורס כדאי במיוחד לשמר, ומדוע?','أي لقاء أو عنصر في الدورة يستحق الحفاظ عليه بشكل خاص، ولماذا؟'),
('question','איזה שינוי בהכשרה או בהיערכות יעזור לך להדריך את התוכנית טוב יותר?','ما التغيير في التدريب أو الاستعدادات الذي سيساعدك على إرشاد البرنامج بصورة أفضل؟'),
('question','איזה תחום הכי חשוב לשפר לקראת המחזור הבא?','ما المجال الأهم الذي ينبغي تحسينه للدورة القادمة؟'),
('question','איזה תחום חשוב ביותר לשפר לקראת הפעלת הקורס הבאה?','ما المجال الأكثر أهمية للتحسين قبل تنفيذ الدورة مرة أخرى؟'),
('question','איזו פעילות או התנסות הייתה הכי משמעותית בשבילך, ולמה?','أي نشاط أو تجربة كان الأكثر أهمية بالنسبة إليك، ولماذا؟'),
('question','איזו פעילות הכי אהבת בתוכנית?','أي نشاط أحببته أكثر في البرنامج؟'),
('question','איזו פעילות הכי עניינה אותך בתוכנית?','أي نشاط أثار اهتمامك أكثر في البرنامج؟'),
('question','איזו פעילות, דמות או שיחה נשארה איתך במיוחד?','أي نشاط أو شخصية أو حوار بقي في ذاكرتك بشكل خاص؟'),
('question','איך היית מתאר/ת את רמת העומס של התוכן?','كيف تصف مستوى كثافة المحتوى؟'),
('question','אם היית מעביר/ה את התוכנית שוב, מה היית עושה אחרת?','لو قدّمت البرنامج مرة أخرى، ماذا كنت ستفعل بشكل مختلف؟'),
('question','אני אוהב/ת לשאול שאלות ולחקור איך דברים עובדים','أحب طرح الأسئلة واستكشاف كيفية عمل الأشياء'),
('question','אני בוחן/ת באופן ביקורתי את היתרונות והסיכונים של שימוש בבינה מלאכותית','أقيّم بصورة نقدية فوائد استخدام الذكاء الاصطناعي ومخاطره'),
('question','אני גאה במשחק שפיתחנו ויכול/ה להסביר לאחרים איך משחקים בו','أشعر بالفخر باللعبة التي طوّرناها، وأستطيع شرح طريقة اللعب للآخرين'),
('question','אני חושב/ת שמדע וטכנולוגיה יכולים לעזור לפתור בעיות אמיתיות בעולם','أعتقد أن العلوم والتكنولوجيا يمكنهما المساعدة في حل مشكلات حقيقية في العالم'),
('question','אני יודע/ת איזה מידע אישי לא כדאי להכניס לכלי בינה מלאכותית.','أعرف ما المعلومات الشخصية التي لا ينبغي إدخالها إلى أدوات الذكاء الاصطناعي.'),
('question','אני יודע/ת איך לבדוק אם כבר יש פתרונות דומים לרעיון שלי.','أعرف كيف أتحقق مما إذا كانت هناك حلول مشابهة لفكرتي.'),
('question','אני יודע/ת איך לנסח בקשה ברורה כדי לקבל תשובה שימושית מכלי בינה מלאכותית.','أعرف كيف أصوغ طلبًا واضحًا للحصول على إجابة مفيدة من أداة ذكاء اصطناعي.'),
('question','אני יודע/ת להנחות בנייה, בדיקה ושיפור של דגם.','أعرف كيف أرشد عملية بناء نموذج واختباره وتحسينه.'),
('question','אני יודע/ת להנחות הכנת פוסטר שמסביר בעיה ופתרון.','أعرف كيف أرشد إعداد ملصق يشرح مشكلة وحلّها.'),
('question','אני יודע/ת להנחות חקר של מנגנון בטבע עם תלמידי ד׳–ו׳.','أعرف كيف أرشد طلاب الصفوف الرابع حتى السادس إلى بحث آلية موجودة في الطبيعة.'),
('question','אני יודע/ת להנחות קבוצה לזהות צורך אמיתי ולהגדיר למי הפתרון מיועד.','أعرف كيف أرشد مجموعة إلى تحديد حاجة حقيقية وتوضيح الفئة المستهدفة بالحل.'),
('question','אני יודע/ת להנחות שיח מותאם גיל על אמינות, פרטיות והטיות של בינה מלאכותית.','أعرف كيف أدير نقاشًا مناسبًا للفئة العمرية حول موثوقية الذكاء الاصطناعي والخصوصية والتحيّز.'),
('question','אני יודע/ת להנחות תלמידים לזהות בעיה מהחיים בחלל.','أعرف كيف أرشد الطلاب إلى تحديد مشكلة تتعلق بالحياة في الفضاء.'),
('question','אני יודע/ת להנחות תלמידים לזהות בעיה סביבתית בבית הספר.','أعرف كيف أرشد الطلاب إلى تحديد مشكلة بيئية في المدرسة.'),
('question','אני יודע/ת להנחות תלמידים לזהות צורך של מטופלים ולחשוב על פתרון מתאים.','أعرف كيف أرشد الطلاب إلى تحديد حاجة لدى المرضى والتفكير في حل مناسب.'),
('question','אני יודע/ת להנחות תלמידים לחשב עלויות בסיסיות ולבחון מחיר אפשרי למוצר.','أعرف كيف أرشد الطلاب إلى حساب التكاليف الأساسية وتقدير سعر محتمل للمنتج.'),
('question','אני יודע/ת להנחות תלמידים לנסח בקשה ברורה לכלי בינה מלאכותית ולשפר אותה.','أعرف كيف أرشد الطلاب إلى صياغة طلب واضح لأداة ذكاء اصطناعي وتحسينه.'),
('question','אני יודע/ת להנחות תלמידים לתכנן פתרון לבעיה מהחיים בחלל.','أعرف كيف أرشد الطلاب إلى تخطيط حل لمشكلة تتعلق بالحياة في الفضاء.'),
('question','אני יודע/ת להסביר למה הרעיון שלי יכול לעזור.','أعرف كيف أشرح لماذا يمكن أن تكون فكرتي مفيدة.'),
('question','אני יודע/ת להציע דרך פשוטה לצמצם בזבוז בבית או בבית הספר.','أعرف كيف أقترح طريقة بسيطة لتقليل الهدر في المنزل أو المدرسة.'),
('question','אני יודע/ת לזהות בעיה בחיי היום־יום שכדאי למצוא לה פתרון.','أعرف كيف أحدد مشكلة في الحياة اليومية تستحق إيجاد حل لها.'),
('question','אני יודע/ת לזהות בעיה של אנשים שכדאי למצוא לה פתרון.','أعرف كيف أحدد مشكلة يواجهها الناس وتستحق إيجاد حل لها.'),
('question','אני יודע/ת לזהות מנגנון בטבע ולהסביר את עקרון הפעולה שלו','أعرف كيف أحدد آلية في الطبيعة وأشرح مبدأ عملها'),
('question','אני יודע/ת לחבר בין אתגר בחלל לבין פתרון מדעי או הנדסי אפשרי','أعرف كيف أربط بين تحدٍّ في الفضاء وحل علمي أو هندسي ممكن'),
('question','אני יודע/ת לחפש מידע שיעזור לי להבין בעיה ולבחור פתרון.','أعرف كيف أبحث عن معلومات تساعدني على فهم مشكلة واختيار حل.'),
('question','אני יודע/ת לחשוב אילו חומרים או משאבים צריך למוצר וכמה הם עשויים לעלות.','أعرف كيف أحدد المواد أو الموارد اللازمة لمنتج ما وأقدّر تكلفتها.'),
('question','אני יודע/ת ללוות קבוצה מתכנון רעיון סביבתי ועד הצגת יוזמה.','أعرف كيف أرافق مجموعة من تخطيط فكرة بيئية حتى عرض مبادرة.'),
('question','אני יודע/ת ללוות קבוצת תלמידים מחקר צורך ועד להצגת רעיון למוצר רפואי.','أعرف كيف أرافق مجموعة طلاب من بحث حاجة حتى عرض فكرة لمنتج طبي.'),
('question','אני יודע/ת למה קשה לחיות בחלל בלי ציוד מיוחד.','أعرف لماذا يصعب العيش في الفضاء من دون معدات خاصة.'),
('question','אני יודע/ת לעבוד בצוות כדי לפתח רעיון משותף','أعرف كيف أعمل ضمن فريق لتطوير فكرة مشتركة'),
('question','אני יודע/ת לתכנן רעיון למשחק עם חוקים ברורים, אתגר ותנאי ניצחון','أعرف كيف أخطط لفكرة لعبة ذات قواعد واضحة وتحدٍّ وشروط للفوز'),
('question','אני יודע/ת לתרגם עיקרון מהטבע לרעיון טכנולוגי שיכול לפתור צורך אנושי','أعرف كيف أحوّل مبدأ من الطبيعة إلى فكرة تكنولوجية يمكنها تلبية حاجة إنسانية'),
('question','אני יודעת להנחות נערות לזהות בעיה אמיתית ולבחור כיוון לפתרון.','أعرف كيف أرشد فتيات إلى تحديد مشكلة حقيقية واختيار اتجاه للحل.'),
('question','אני יודעת ללוות צוות נערות מהרעיון ועד להצגת מיזם.','أعرف كيف أرافق فريقًا من الفتيات من مرحلة الفكرة حتى عرض المبادرة.'),
('question','אני יכול/ה להסביר איך בינה מלאכותית משמשת בתחומים כמו רפואה, חקלאות, תעשייה ותחבורה','أستطيع شرح كيفية استخدام الذكاء الاصطناعي في مجالات مثل الطب والزراعة والصناعة والمواصلات'),
('question','אני יכול/ה להסביר בקצרה מה עושים בתחום פיתוח התרופות.','أستطيع أن أشرح بإيجاز ما الذي يحدث في مجال تطوير الأدوية.'),
('question','אני יכול/ה להסביר למה רעיון אחד יכול להתאים יותר מרעיון אחר.','أستطيع أن أشرح لماذا قد تكون فكرة أنسب من فكرة أخرى.'),
('question','אני יכול/ה להסביר מה היתרון של הרעיון שלי לעומת פתרון אחר.','أستطيع شرح ميزة فكرتي مقارنة بحل آخر.'),
('question','אני יכול/ה להציע דרך להמחיש רעיון למוצר בעזרת דגם או ציור.','أستطيع اقتراح طريقة لتوضيح فكرة منتج بواسطة نموذج أو رسم.'),
('question','אני יכול/ה להציע רעיון שיעזור לשפר משהו בסביבה שלי.','أستطيع اقتراح فكرة تساعد على تحسين شيء في بيئتي.'),
('question','אני יכול/ה לחשוב על דרך שבה בינה מלאכותית תעזור לפתור בעיה.','أستطيع التفكير في طريقة يمكن للذكاء الاصطناعي أن يساعد بها على حل مشكلة.'),
('question','אני יכול/ה לחשוב על רעיון שיעזור לאנשים בחלל.','أستطيع التفكير في فكرة تساعد الناس في الفضاء.'),
('question','אני יכול/ה לתת דוגמה למשהו שאנשים עושים ופוגע בסביבה.','أستطيع إعطاء مثال على تصرف بشري يضر بالبيئة.'),
('question','אני יכול/ה לתת דוגמה למשהו שבינה מלאכותית עושה בחיי היום־יום.','أستطيع إعطاء مثال على استخدام للذكاء الاصطناعي في الحياة اليومية.'),
('question','אני יכולה להסביר למי הרעיון שלי מיועד ולמה הוא חשוב.','أستطيع شرح الفئة التي تستهدفها فكرتي ولماذا هي مهمة.'),
('question','אני יכולה לחשוב על רעיון שיעזור לפתור בעיה אמיתית.','أستطيع التفكير في فكرة تساعد على حل مشكلة حقيقية.'),
('question','אני מאמין/ה שאני מסוגל/ת לפתח רעיון לפתרון של בעיה אמיתית','أؤمن بقدرتي على تطوير فكرة لحل مشكلة حقيقية'),
('question','אני מבין/ה איך ביומימיקרי יכול לעזור לפתח פתרונות מקיימים ואחראיים יותר','أفهم كيف يمكن للمحاكاة الحيوية أن تساعد على تطوير حلول أكثر استدامة ومسؤولية'),
('question','אני מבין/ה איך דוגמאות ומידע עוזרים למערכת בינה מלאכותית ללמוד.','أفهم كيف تساعد الأمثلة والبيانات نظام الذكاء الاصطناعي على التعلّم.'),
('question','אני מבין/ה איך חוקים, מטרות ואתגרים משפיעים על חוויית המשחק','أفهم كيف تؤثر القواعد والأهداف والتحديات على تجربة اللعب'),
('question','אני מבין/ה את השאלות האתיות והחברתיות שהבינה המלאכותית מעוררת (למשל פרטיות, אמון ותעסוקה)','أفهم القضايا الأخلاقية والاجتماعية التي يثيرها الذكاء الاصطناعي، مثل الخصوصية والثقة والعمل'),
('question','אני מבין/ה כיצד לוויינים וטכנולוגיות חלל משפיעים על החיים בכדור הארץ','أفهم كيف تؤثر الأقمار الصناعية وتكنولوجيا الفضاء على الحياة على الأرض'),
('question','אני מבין/ה למה צריך לבדוק טיפול חדש לפני שמשתמשים בו.','أفهم لماذا يجب اختبار علاج جديد قبل استخدامه.'),
('question','אני מבין/ה מה לומדים בתחום {topic} ואיך משתמשים בו בעולם האמיתי','أفهم ما نتعلّمه في مجال {topic} وكيف نستخدمه في العالم الحقيقي'),
('question','אני מבין/ה שגם תשובה של כלי בינה מלאכותית יכולה להיות לא הוגנת או מוטה.','أفهم أن إجابة أداة الذكاء الاصطناعي قد تكون غير عادلة أو متحيّزة.'),
('question','אני מכיר/ה משהו שהמציאו בשביל החלל ומשתמשים בו גם בכדור הארץ.','أعرف شيئًا اختُرع لاستخدامه في الفضاء ويُستخدم أيضًا على الأرض.'),
