-- Arabic translations for all existing feedback templates.
-- Keep original Hebrew, question IDs and answer values intact.
-- Translation map also allows already-issued links to render Arabic without
-- changing the version snapshot or previously submitted responses.

create table if not exists private.feedback_arabic_translations (
  kind text not null check (kind in ('question','intro','option')),
  he text not null,
  ar text not null check (btrim(ar) <> ''),
  primary key (kind, he)
);
revoke all on private.feedback_arabic_translations from public, anon, authenticated;

on conflict (kind,he) do update set ar=excluded.ar;

-- Preserve already-approved Arabic wording and option translations.
select 'question', q.wording->>'default', min(q.wording->>'ar')
from public.feedback_template_questions q
where coalesce(q.wording->>'ar','') <> ''
group by q.wording->>'default'
on conflict do nothing;

select 'option', o.value->>'label', min(o.value->>'label_ar')
from public.feedback_template_questions q
cross join lateral jsonb_array_elements(q.options) o(value)
where coalesce(o.value->>'label_ar','') <> ''
group by o.value->>'label'
on conflict do nothing;

select 'intro', v.intro_text, min(v.intro_text_ar)
from public.feedback_template_versions v
where coalesce(v.intro_text_ar,'') <> ''
group by v.intro_text
on conflict do nothing;

-- Replays are harmless: only templates whose current published version lacks
-- Arabic translations are eligible for a new translated version.
create temporary table feedback_ar_target_templates(template_id uuid primary key) on commit drop;
select t.id from public.feedback_templates t
join public.feedback_template_versions v on v.id=t.current_version_id
where coalesce(v.intro_text_ar,'')=''
   or exists(
     select 1 from public.feedback_template_questions q
     where q.version_id=t.current_version_id
       and (coalesce(q.wording->>'ar','')='' or exists(
         select 1 from jsonb_array_elements(q.options) o
         where coalesce(o->>'label_ar','')=''
       ))
   );

-- Create independent edit-ready copies; never edit locked published snapshots.
select t.id,
  (select coalesce(max(x.version_no),0)+1 from public.feedback_template_versions x where x.template_id=t.id),
  'draft',v.intro_text,v.intro_text_ar,'תרגום ערבי – שמירת נוסח עברי'
from public.feedback_templates t
join feedback_ar_target_templates target on target.template_id=t.id
join public.feedback_template_versions v on v.id=t.current_version_id
where not exists(select 1 from public.feedback_template_versions d where d.template_id=t.id and d.status='draft');

  version_id,question_id,section,sort_order,required,metric_key,question_type,is_comparison,wording,options,scoring
)
select d.id,q.question_id,q.section,q.sort_order,q.required,q.metric_key,q.question_type,q.is_comparison,q.wording,q.options,q.scoring
from public.feedback_templates t
join feedback_ar_target_templates target on target.template_id=t.id
join public.feedback_template_versions d on d.template_id=t.id and d.status='draft'
join public.feedback_template_questions q on q.version_id=t.current_version_id
where not exists(select 1 from public.feedback_template_questions already where already.version_id=d.id and already.question_id=q.question_id);

update public.feedback_template_questions q
set wording=jsonb_set(q.wording,'{ar}',to_jsonb(m.ar),true)
from public.feedback_template_versions v, private.feedback_arabic_translations m
where q.version_id=v.id and v.status='draft' and v.template_id in (select template_id from feedback_ar_target_templates) and m.kind='question'
  and q.wording->>'default'=m.he and coalesce(q.wording->>'ar','')='';

update public.feedback_template_versions v
set intro_text_ar=m.ar
from private.feedback_arabic_translations m
where v.status='draft' and v.template_id in (select template_id from feedback_ar_target_templates) and m.kind='intro'
  and v.intro_text=m.he and coalesce(v.intro_text_ar,'')='';

update public.feedback_template_questions q
set options=(
 select coalesce(jsonb_agg(
   case when coalesce(o.elem->>'label_ar','')='' and m.ar is not null
        then jsonb_set(o.elem,'{label_ar}',to_jsonb(m.ar),true)
        else o.elem end order by o.ord),'[]'::jsonb)
 from jsonb_array_elements(q.options) with ordinality o(elem,ord)
 left join private.feedback_arabic_translations m
   on m.kind='option' and m.he=o.elem->>'label'
)
where q.version_id in (select id from public.feedback_template_versions where status='draft' and template_id in (select template_id from feedback_ar_target_templates))
  and jsonb_typeof(q.options)='array' and q.options <> '[]'::jsonb;

-- Localize the question bank as well, so reusing a question retains its translation.
update public.feedback_questions q
set wording=jsonb_set(q.wording,'{ar}',to_jsonb(m.ar),true)
from private.feedback_arabic_translations m
where m.kind='question' and q.wording->>'default'=m.he and coalesce(q.wording->>'ar','')='';

update public.feedback_questions q
set options=(
 select coalesce(jsonb_agg(
   case when coalesce(o.elem->>'label_ar','')='' and m.ar is not null
        then jsonb_set(o.elem,'{label_ar}',to_jsonb(m.ar),true)
        else o.elem end order by o.ord),'[]'::jsonb)
 from jsonb_array_elements(q.options) with ordinality o(elem,ord)
 left join private.feedback_arabic_translations m
   on m.kind='option' and m.he=o.elem->>'label'
)
where jsonb_typeof(q.options)='array' and q.options <> '[]'::jsonb;

-- Do not publish unless every field in every questionnaire is fully bilingual.
do $translation_verification$
begin
 if exists (
   select 1 from public.feedback_template_versions v
   join feedback_ar_target_templates target on target.template_id=v.template_id
   join public.feedback_template_questions q on q.version_id=v.id
   where v.status='draft' and (coalesce(q.wording->>'ar','')='' or exists(
     select 1 from jsonb_array_elements(q.options) o
     where coalesce(o->>'label_ar','')=''
   ))
 ) then raise exception 'feedback_arabic_incomplete_question_or_option'; end if;
 if exists (
   select 1 from public.feedback_template_versions v
   join feedback_ar_target_templates target on target.template_id=v.template_id
   where v.status='draft' and coalesce(v.intro_text_ar,'')=''
 ) then raise exception 'feedback_arabic_incomplete_intro'; end if;
end $translation_verification$;

-- For already opened links, use the same translations at render time,
-- preserving the original questionnaire version and all answer IDs.
create or replace function public.feedback_public_get(p_token text)
returns jsonb
language plpgsql stable security definer set search_path to ''
as $function$
declare
  v_target record;
  v_state text;
  c public.feedback_campaigns;
  v_program public.feedback_programs;
  v_recipient_name text;
  v_topic_ar text;
begin
  select * into v_target from private.feedback_token_target(p_token,false) limit 1;
  if v_target.campaign_id is null then
    return jsonb_build_object('state','invalid');
  end if;
  select * into c from public.feedback_campaigns where id=v_target.campaign_id;
  select * into v_program from public.feedback_programs where key=c.program_key;
  v_state:=private.feedback_public_state(c.id,v_target.recipient_id);
  if v_target.recipient_id is not null then
    select display_name into v_recipient_name from public.feedback_recipients where id=v_target.recipient_id;
  end if;
  v_topic_ar:=case v_program.key
    when 'biomimicry' then 'المحاكاة الحيوية – ابتكارات مستوحاة من الطبيعة'
    when 'biomimicry_secondary' then 'المحاكاة الحيوية والاستدامة والابتكار التكنولوجي'
    when 'board_games' then 'تطوير ألعاب الطاولة والاستراتيجيات وتخطيط الألعاب'
    when 'green_leadership' then 'الاستدامة والقيادة البيئية'
    when 'space_tech' then 'تكنولوجيا الفضاء'
    when 'sky_limit' then 'الفضاء والأقمار الصناعية وتكنولوجيا الفضاء'
    when 'ai_applications' then 'تطبيقات الذكاء الاصطناعي'
    when 'ai_foundations' then 'الذكاء الاصطناعي'
    when 'pharma' then 'تطوير الأدوية والصناعة الدوائية'
    when 'ofek' then 'ريادة الأعمال والصناعة'
    when 'trailblazers' then 'ريادة الأعمال والتكنولوجيا'
    else v_program.topic end;
  return jsonb_build_object(
    'state',v_state,'audience',c.audience,'stage',c.stage,
    'age_band',c.age_band,'program_title',v_program.title,
    'school_name',c.school_name,'grade',c.grade,
    'recipient_name',coalesce(v_recipient_name,''),
    'expires_at',c.expires_at,
    'intro_text',(select intro_text from public.feedback_template_versions where id=c.template_version_id),
    'intro_text_ar',coalesce(
      (select nullif(intro_text_ar,'') from public.feedback_template_versions where id=c.template_version_id),
      (select m.ar from private.feedback_arabic_translations m
       join public.feedback_template_versions v on v.intro_text=m.he
       where v.id=c.template_version_id and m.kind='intro')),
    'questions',case when v_state<>'ok' then '[]'::jsonb else coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',tq.id,
        'type',tq.question_type,
        'text',replace(tq.wording->>'default','{topic}',v_program.topic),
        'text_ar',nullif(replace(
          coalesce(nullif(tq.wording->>'ar',''),
            (select m.ar from private.feedback_arabic_translations m
             where m.kind='question' and m.he=tq.wording->>'default'),''),
          '{topic}',v_topic_ar),''),
        'options',case when jsonb_typeof(tq.options)='array' then
          (select coalesce(jsonb_agg(
            case when coalesce(o.elem->>'label_ar','')='' and m.ar is not null
              then jsonb_set(o.elem,'{label_ar}',to_jsonb(m.ar),true)
              else o.elem end order by o.ord),'[]'::jsonb)
           from jsonb_array_elements(tq.options) with ordinality o(elem,ord)
           left join private.feedback_arabic_translations m on m.kind='option' and m.he=o.elem->>'label'
          ) else tq.options end,
        'required',tq.required,
        'section',tq.section,
        'allow_na',(tq.question_type='rating_1_5' and coalesce(tq.scoring->>'allow_na','')='true')
      ) order by tq.sort_order,tq.id)
      from public.feedback_template_questions tq
      where tq.version_id=c.template_version_id
    ),'[]'::jsonb) end
  );
end
$function$;

do $publish$
declare x record;
begin
 for x in select v.id from public.feedback_template_versions v
   join public.feedback_templates t on t.id=v.template_id
   join feedback_ar_target_templates target on target.template_id=v.template_id
   where v.status='draft' and t.current_version_id is not null
 loop
   perform private.feedback_publish_version(x.id);
 end loop;
end $publish$;
